window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c96c17f7aab74cc9"]={"versions": [{"id": "FIG-c96c17f7aab74cc9", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>sm Socket Handler</code>) der AUTOSAR Classic Platform im Modul Socket Adaptor (<code>SoAd</code>). Es spezifiziert die Kontrollfluss- und Zustandslogik für das dynamische Socket-Ressourcenmanagement (<code>Socket Resource Management</code>) bei eingehenden Socket-Anforderungen (<code>New Socket Request</code>) unter Berücksichtigung von Ressourcenknappheit, Verdrängungsstrategien (LFU/FIFO) und Zählerüberläufen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Start- und Endzustände</strong>: Startknoten (<code>New Socket Request</code>), Endzustand (<code>Final</code>).</li>\n<li><strong>Einfache Zustände / Aktionen</strong>:</li>\n<li><code>Lock Semaphore to prevent parallel access</code></li>\n<li><code>Check if socket is already av ailable in the table</code></li>\n<li><code>Increment Counter in Table</code></li>\n<li><code>Divide all counters by 2</code></li>\n<li><code>Check if enough ressources for a new socket are available</code></li>\n<li><code>Create new Socket</code></li>\n<li><code>Return Socket (or error) to caller</code></li>\n<li><strong>Zusammengesetzte Zustände (Sub-State-Machines / Composite States)</strong>:</li>\n<li><code>Select Socket to Supersede</code>: Enthält <code>Select LFU Socket in Table (lowest counter value)</code> und <code>Select Socket with FIFO Algorithm</code>.</li>\n<li><code>Supersede selected Socket</code>: Enthält <code>Check if data is pending on the selected Socket</code>, <code>Free ressources</code> und <code>Delete Table entry</code>.</li>\n<li><strong>Bedingungen / Guards / Transitionsevents</strong>: <code>Socket not available</code>, <code>Insufficient ressources</code>, <code>Free ressources available</code>, <code>Counter overflow</code>, <code>Multible Sockets selected</code>, <code>Data pending</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein eingehender Verbindungs-/Socket-Wunsch startet bei <code>New Socket Request</code> und sperrt eine Semaphor-Variable (<code>Lock Semaphore to prevent parallel access</code>).</li>\n<li>Es erfolgt die Prüfung <code>Check if socket is already av ailable in the table</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist der Socket bereits vorhanden, wird <code>Increment Counter in Table</code> ausgeführt. Tritt hierbei ein <code>Counter overflow</code> auf, führt der Übergang zu <code>Divide all counters by 2</code>. Beide Pfade münden anschließend in <code>Return Socket (or error) to caller</code>.</li>\n<li>Ist der Socket nicht vorhanden (<code>Socket not available</code>), verzweigt der Ablauf zu <code>Check if enough ressources for a new socket are available</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>Check if enough ressources for a new socket are available</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sind freie Ressourcen vorhanden (<code>Free ressources available</code>), wird <code>Create new Socket</code> ausgeführt.</li>\n<li>Reichen die Ressourcen nicht aus (<code>Insufficient ressources</code>), wechselt die Steuerung in den Makrozustand <code>Select Socket to Supersede</code> und dort zunächst auf <code>Select LFU Socket in Table (lowest counter value)</code>. Liefern mehrere Sockets denselben niedrigsten Zählerwert (<code>Multible Sockets selected</code>), entscheidet <code>Select Socket with FIFO Algorithm</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der ausgewählte Socket wird in <code>Supersede selected Socket</code> überführt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zunächst prüft <code>Check if data is pending on the selected Socket</code>. Liegen noch Daten an (<code>Data pending</code>), verharrt die Bearbeitung in einer Selbst-Transition.</li>\n<li>Sobald keine Daten mehr anstehen, folgt <code>Free ressources</code> und anschließend <code>Delete Table entry</code>.</li>\n<li>Nach dem Löschen des Tabelleneintrags führt der Pfad zurück zu <code>Create new Socket</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach <code>Create new Socket</code> erfolgt der Übergang zu <code>Return Socket (or error) to caller</code>.</li>\n<li>Von <code>Return Socket (or error) to caller</code> schließt der Ablauf im Endzustand <code>Final</code> ab (wobei die Freigabe des Semaphors implizit mit der Rückkehr an den Aufrufer verknüpft ist).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das deterministische Verhalten des <code>SoAd</code> bei Socket-Erschöpfung: Primäres Verdrängungskriterium ist Least Frequently Used (LFU), Sekundärkriterium bei Gleichstand ist First In First Out (FIFO).</li>\n<li>Vor der Freigabe eines zu verdrängenden Sockets muss sichergestellt werden, dass keine unübertragenen/anstehenden Nutzdaten (<code>Data pending</code>) verloren gehen.</li>\n<li>Schutz vor Deadlocks/Race-Conditions durch Semaphore-Sperre; Entwickler müssen sicherstellen, dass in allen Pfaden (Erfolg oder Fehler) der Zugriff synchronisiert bleibt und keine Semaphor-Blockaden verbleiben.</li>\n<li>Zur Vermeidung von Zählerüberläufen bei LFU-Nutzungszählern (<code>Counter overflow</code>) ist eine Skalierung (<code>Divide all counters by 2</code>) vorgeschrieben.</li>\n<li>Die Schreibweise <code>av ailable</code> im Zustand <code>Check if socket is already av ailable in the table</code> stellt einen redaktionellen Tippfehler der Spezifikation dar, ändert jedoch nichts an der geforderten Prüfsemantik auf Vorhandensein in der Socket-Verwaltungstabelle.</li>\n</ul>"}, {"id": "FIG-652ed43fdba6657f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>sm Socket Handler</code>) der AUTOSAR Classic Platform im Modul Socket Adaptor (<code>SoAd</code>). Es spezifiziert die Kontrollfluss- und Zustandslogik für das dynamische Socket-Ressourcenmanagement (<code>Socket Resource Management</code>) bei eingehenden Socket-Anforderungen (<code>New Socket Request</code>) unter Berücksichtigung von Ressourcenknappheit, Verdrängungsstrategien (LFU/FIFO) und Zählerüberläufen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Start- und Endzustände</strong>: Startknoten (<code>New Socket Request</code>), Endzustand (<code>Final</code>).</li>\n<li><strong>Einfache Zustände / Aktionen</strong>:</li>\n<li><code>Lock Semaphore to prevent parallel access</code></li>\n<li><code>Check if socket is already available in the table</code></li>\n<li><code>Increment Counter in Table</code></li>\n<li><code>Divide all counters by 2</code></li>\n<li><code>Check if enough ressources for a new socket are available</code></li>\n<li><code>Create new Socket</code></li>\n<li><code>Return Socket (or error) to caller</code></li>\n<li><strong>Zusammengesetzte Zustände (Sub-State-Machines / Composite States)</strong>:</li>\n<li><code>Select Socket to Supersede</code>: Enthält <code>Select LFU Socket in Table (lowest counter value)</code> und <code>Select Socket with FIFO Algorithm</code>.</li>\n<li><code>Supersede selected Socket</code>: Enthält <code>Check if data is pending on the selected Socket</code>, <code>Free ressources</code> und <code>Delete Table entry</code>.</li>\n<li><strong>Bedingungen / Guards / Transitionsevents</strong>: <code>Socket not available</code>, <code>Insufficient ressources</code>, <code>Free ressources available</code>, <code>Counter overflow</code>, <code>Multible Sockets selected</code>, <code>Data pending</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein eingehender Verbindungs-/Socket-Wunsch startet bei <code>New Socket Request</code> und sperrt eine Semaphor-Variable (<code>Lock Semaphore to prevent parallel access</code>).</li>\n<li>Es erfolgt die Prüfung <code>Check if socket is already available in the table</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist der Socket bereits vorhanden, wird <code>Increment Counter in Table</code> ausgeführt. Tritt hierbei ein <code>Counter overflow</code> auf, führt der Übergang zu <code>Divide all counters by 2</code>. Beide Pfade münden anschließend in <code>Return Socket (or error) to caller</code>.</li>\n<li>Ist der Socket nicht vorhanden (<code>Socket not available</code>), verzweigt der Ablauf zu <code>Check if enough ressources for a new socket are available</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>Check if enough ressources for a new socket are available</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sind freie Ressourcen vorhanden (<code>Free ressources available</code>), wird <code>Create new Socket</code> ausgeführt.</li>\n<li>Reichen die Ressourcen nicht aus (<code>Insufficient ressources</code>), wechselt die Steuerung in den Makrozustand <code>Select Socket to Supersede</code> und dort zunächst auf <code>Select LFU Socket in Table (lowest counter value)</code>. Liefern mehrere Sockets denselben niedrigsten Zählerwert (<code>Multible Sockets selected</code>), entscheidet <code>Select Socket with FIFO Algorithm</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der ausgewählte Socket wird in <code>Supersede selected Socket</code> überführt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zunächst prüft <code>Check if data is pending on the selected Socket</code>. Liegen noch Daten an (<code>Data pending</code>), verharrt die Bearbeitung in einer Selbst-Transition.</li>\n<li>Sobald keine Daten mehr anstehen, folgt <code>Free ressources</code> und anschließend <code>Delete Table entry</code>.</li>\n<li>Nach dem Löschen des Tabelleneintrags führt der Pfad zurück zu <code>Create new Socket</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach <code>Create new Socket</code> erfolgt der Übergang zu <code>Return Socket (or error) to caller</code>.</li>\n<li>Von <code>Return Socket (or error) to caller</code> schließt der Ablauf im Endzustand <code>Final</code> ab (wobei die Freigabe des Semaphors implizit mit der Rückkehr an den Aufrufer verknüpft ist).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das deterministische Verhalten des <code>SoAd</code> bei Socket-Erschöpfung: Primäres Verdrängungskriterium ist Least Frequently Used (LFU), Sekundärkriterium bei Gleichstand ist First In First Out (FIFO).</li>\n<li>Vor der Freigabe eines zu verdrängenden Sockets muss sichergestellt werden, dass keine unübertragenen/anstehenden Nutzdaten (<code>Data pending</code>) verloren gehen.</li>\n<li>Schutz vor Deadlocks/Race-Conditions durch Semaphore-Sperre; Entwickler müssen sicherstellen, dass in allen Pfaden (Erfolg oder Fehler) der Zugriff synchronisiert bleibt und keine Semaphor-Blockaden verbleiben.</li>\n<li>Zur Vermeidung von Zählerüberläufen bei LFU-Nutzungszählern (<code>Counter overflow</code>) ist eine Skalierung (<code>Divide all counters by 2</code>) vorgeschrieben.</li>\n</ul>"}, {"id": "FIG-cf221f46756410c0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>sm Socket Handler</code>) der AUTOSAR Classic Platform im Modul Socket Adaptor (<code>SoAd</code>). Es spezifiziert die Kontrollfluss- und Zustandslogik für das dynamische Socket-Ressourcenmanagement (<code>Socket Resource Management</code>) bei eingehenden Socket-Anforderungen (<code>New Socket Request</code>) unter Berücksichtigung von Ressourcenknappheit, Verdrängungsstrategien (LFU/FIFO) und Zählerüberläufen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Start- und Endzustände</strong>: Startknoten (<code>New Socket Request</code>), Endzustand (<code>Final</code>).</li>\n<li><strong>Einfache Zustände / Aktionen</strong>:</li>\n<li><code>Lock Semaphore to prevent parallel access</code></li>\n<li><code>Check if socket is already available in the table</code></li>\n<li><code>Increment Counter in Table</code></li>\n<li><code>Divide all counters by 2</code></li>\n<li><code>Check if enough ressources for a new socket are available</code></li>\n<li><code>Create new Socket</code></li>\n<li><code>Return Socket (or error) to caller</code></li>\n<li><strong>Zusammengesetzte Zustände (Sub-State-Machines / Composite States)</strong>:</li>\n<li><code>Select Socket to Supersede</code>: Enthält <code>Select LFU Socket in Table (lowest counter value)</code> und <code>Select Socket with FIFO Algorithm</code>.</li>\n<li><code>Supersede selected Socket</code>: Enthält <code>Check if data is pending on the selected Socket</code>, <code>Free ressources</code> und <code>Delete Table entry</code>.</li>\n<li><strong>Bedingungen / Guards / Transitionsevents</strong>: <code>Socket not available</code>, <code>Insufficient ressources</code>, <code>Free ressources available</code>, <code>Counter overflow</code>, <code>Multible Sockets selected</code>, <code>Data pending</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein eingehender Verbindungs-/Socket-Wunsch startet bei <code>New Socket Request</code> und sperrt eine Semaphor-Variable (<code>Lock Semaphore to prevent parallel access</code>).</li>\n<li>Es erfolgt die Prüfung <code>Check if socket is already available in the table</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist der Socket bereits vorhanden, wird <code>Increment Counter in Table</code> ausgeführt. Tritt hierbei ein <code>Counter overflow</code> auf, führt der Übergang zu <code>Divide all counters by 2</code>. Beide Pfade münden anschließend in <code>Return Socket (or error) to caller</code>.</li>\n<li>Ist der Socket nicht vorhanden (<code>Socket not available</code>), verzweigt der Ablauf zu <code>Check if enough ressources for a new socket are available</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>Check if enough ressources for a new socket are available</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sind freie Ressourcen vorhanden (<code>Free ressources available</code>), wird <code>Create new Socket</code> ausgeführt.</li>\n<li>Reichen die Ressourcen nicht aus (<code>Insufficient ressources</code>), wechselt die Steuerung in den Makrozustand <code>Select Socket to Supersede</code> und dort zunächst auf <code>Select LFU Socket in Table (lowest counter value)</code>. Liefern mehrere Sockets denselben niedrigsten Zählerwert (<code>Multible Sockets selected</code>), entscheidet <code>Select Socket with FIFO Algorithm</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der ausgewählte Socket wird in <code>Supersede selected Socket</code> überführt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zunächst prüft <code>Check if data is pending on the selected Socket</code>. Liegen noch Daten an (<code>Data pending</code>), verharrt die Bearbeitung in einer Selbst-Transition.</li>\n<li>Sobald keine Daten mehr anstehen, folgt <code>Free ressources</code> und anschließend <code>Delete Table entry</code>.</li>\n<li>Nach dem Löschen des Tabelleneintrags führt der Pfad zurück zu <code>Create new Socket</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach <code>Create new Socket</code> erfolgt der Übergang zu <code>Return Socket (or error) to caller</code>.</li>\n<li>Von <code>Return Socket (or error) to caller</code> schließt der Ablauf im Endzustand <code>Final</code> ab (wobei die Freigabe des Semaphors implizit mit der Rückkehr an den Aufrufer verknüpft ist).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das deterministische Verhalten des <code>SoAd</code> bei Socket-Erschöpfung: Primäres Verdrängungskriterium ist Least Frequently Used (LFU), Sekundärkriterium bei Gleichstand ist First In First Out (FIFO).</li>\n<li>Vor der Freigabe eines zu verdrängenden Sockets muss sichergestellt werden, dass keine unübertragenen/anstehenden Nutzdaten (<code>Data pending</code>) verloren gehen.</li>\n<li>Schutz vor Deadlocks/Race-Conditions durch Semaphore-Sperre; Entwickler müssen sicherstellen, dass in allen Pfaden (Erfolg oder Fehler) der Zugriff synchronisiert bleibt und keine Semaphor-Blockaden verbleiben.</li>\n<li>Zur Vermeidung von Zählerüberläufen bei LFU-Nutzungszählern (<code>Counter overflow</code>) ist eine Skalierung (<code>Divide all counters by 2</code>) vorgeschrieben.</li>\n</ul>"}], "trans": [{"from": "FIG-c96c17f7aab74cc9", "to": "FIG-652ed43fdba6657f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Beschriftungsfehler im Zustand <code>Check if socket is already av ailable in the table</code> korrigiert zu <code>Check if socket is already available in the table</code> (überflüssiges Leerzeichen im Wort „available“ entfernt).</li>\n<li>Minimales Re-Rendering des Diagrammrahmens (Bildbreite 998 px auf 999 px angepasst).</li>\n</ul>"}, {"from": "FIG-652ed43fdba6657f", "to": "FIG-cf221f46756410c0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
